function initContactForm(){var form=document.getElementById("contact-form"),successMsg=document.getElementById("form-success");if(form){var btn=form.querySelector('button[type="submit"]'),btnDefaultHtml=btn?btn.innerHTML:"Send Message";form.addEventListener("submit",async function(e){e.preventDefault();var fields=form.querySelectorAll("input[required], textarea[required], select[required]"),valid=!0;if(fields.forEach(function(f){f.classList.remove("error"),("SELECT"===f.tagName?!f.value:!f.value.trim())&&(f.classList.add("error"),valid=!1)}),valid){btn&&(btn.disabled=!0,btn.textContent="Sending...");try{if(!(await fetch(form.action,{method:"POST",body:new FormData(form),headers:{Accept:"application/json"}})).ok)throw new Error("Failed");form.style.display="none",successMsg&&successMsg.classList.add("is-visible")}catch(err){btn&&(btn.disabled=!1,btn.innerHTML=btnDefaultHtml),alert("Something went wrong. Please email us directly at info@futureblock.in")}}}),form.querySelectorAll("input, textarea, select").forEach(function(field){field.addEventListener("input",function(){field.classList.remove("error")}),field.addEventListener("change",function(){field.classList.remove("error")})})}}function prefillServiceFromURL(){var service=new URLSearchParams(window.location.search).get("service");if(service){var select=document.querySelector('#contact-form select[name="service"]');if(select){var options=select.querySelectorAll("option"),matched=!1;if(options.forEach(function(opt){opt.value!==service&&opt.textContent.trim()!==service||(opt.selected=!0,matched=!0)}),matched){var placeholder=select.querySelector("option[disabled]");placeholder&&(placeholder.selected=!1),select.style.borderColor="var(--gold)",select.style.background="rgba(200,168,90,0.06)",setTimeout(function(){var contactSection=document.getElementById("contact");contactSection&&contactSection.scrollIntoView({behavior:"smooth",block:"start"})},300)}}}}function initTechAccordion(){document.querySelectorAll(".tech-stack-group").forEach(function(group){var header=group.querySelector(".tech-stack-header");header&&header.addEventListener("click",function(){group.classList.toggle("open")})})}function initTechStagger(){document.querySelectorAll(".tech-card").forEach(function(card,i){card.dataset.delay=String(40*i),card.setAttribute("data-animate","")})}document.addEventListener("DOMContentLoaded",prefillServiceFromURL);